"""Read-only catalogue filters for each line of a sales proposal."""

JS = r'''
function salesArticleSearchText(value){return String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('es')}
function setupSalesArticleSearch(row,fields,article){
 const dataset=$('dataset').value,families=new Set(),familyOf=item=>String(item.family??'').trim();let catalogue=state.articles||[];
 catalogue.forEach(item=>{if(familyOf(item))families.add(familyOf(item))});const toolbar=document.createElement('div');toolbar.className='files-subpanel so-article-search';toolbar.style.gridColumn='1 / -1';const controls=document.createElement('div');controls.className='fields';
 const queryLabel=document.createElement('label'),query=document.createElement('input');queryLabel.textContent='Buscar SKU, descripción o familia';query.type='search';query.autocomplete='off';query.placeholder='Escribe varias palabras para afinar';queryLabel.append(query);
 const familyLabel=document.createElement('label'),family=document.createElement('select');familyLabel.textContent='Familia del artículo';option(family,'','Todas las familias');[...families].sort((a,b)=>a.localeCompare(b,'es',{numeric:true})).forEach(value=>option(family,'family:'+value,value));if(catalogue.some(item=>!familyOf(item)))option(family,'missing','Sin familia documentada');familyLabel.append(family);controls.append(queryLabel,familyLabel);
 const count=document.createElement('p');count.setAttribute('role','status');const clear=document.createElement('button');clear.type='button';clear.textContent='Limpiar búsqueda de artículos';toolbar.append(controls,count,clear);fields.prepend(toolbar);
 function render(){
  if(dataset!==$('dataset').value||state?.info?.dataset_id!==dataset){query.disabled=family.disabled=article.disabled=clear.disabled=true;count.textContent='Actualizando el catálogo de la empresa seleccionada…';return}
  if(state.articles!==catalogue){catalogue=state.articles||[];const savedFamily=family.value;family.replaceChildren();option(family,'','Todas las familias');[...new Set(catalogue.map(familyOf).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'es',{numeric:true})).forEach(value=>option(family,'family:'+value,value));if(catalogue.some(item=>!familyOf(item)))option(family,'missing','Sin familia documentada');if([...family.options].some(item=>item.value===savedFamily))family.value=savedFamily;if(article.value&&!catalogue.some(item=>item.article_id===article.value)){invalidateSalesProposal();row.soRequest=(row.soRequest||0)+1;row.soLoading=false;row.soHint?.replaceChildren();salesLineField(row,'unit_price').value='';syncSalesProposalActions()}}
  const drafts=state.sales_catalogue?.prepared_references||[];
  const selected=article.value,terms=salesArticleSearchText(query.value.trim()).split(/\s+/).filter(Boolean),matches=catalogue.filter(item=>{const text=salesArticleSearchText([item.article_id,item.description,familyOf(item)].join(' '));return terms.every(term=>text.includes(term))&&(!family.value||(family.value==='missing'?!familyOf(item):family.value==='family:'+familyOf(item)))}).sort((a,b)=>a.article_id.localeCompare(b.article_id,'es',{numeric:true})),visible=matches.slice(0,200);
  article.replaceChildren();option(article,'','Selecciona un artículo');visible.forEach(item=>option(article,item.article_id,item.article_id+' · '+(item.description||'')+' / '+item.unit_as_documented));const retained=selected&&!visible.some(item=>item.article_id===selected)?catalogue.find(item=>item.article_id===selected):null;if(retained){const group=document.createElement('optgroup');group.label='Artículo ya seleccionado · conservado fuera de estos resultados';option(group,retained.article_id,retained.article_id+' · '+(retained.description||'')+' / '+retained.unit_as_documented);article.append(group)}
  if(drafts.length){const group=document.createElement('optgroup');group.label='Referencias de ventas pendientes de revisar';drafts.forEach(item=>{const entry=document.createElement('option');entry.value=item.proposed_article_id;entry.textContent=(item.description||item.source_line_id)+' · ficha pendiente';entry.disabled=true;group.append(entry)});article.append(group)}
  article.value=selected&&catalogue.some(item=>item.article_id===selected)?selected:'';count.textContent=stockNumber(matches.length)+' de '+stockNumber(catalogue.length)+' artículos de catálogo · mostrando '+stockNumber(visible.length)+'.'+(matches.length>200?' Afina la búsqueda para ver los demás resultados.':'')+(retained?' El artículo ya seleccionado se conserva aparte y no coincide con los resultados visibles.':'')+(!matches.length?' No hay coincidencias; limpia o cambia los filtros.':'');clear.disabled=!query.value&&!family.value;
 }
 for(const eventName of ['input','change']){query.addEventListener(eventName,event=>{event.stopPropagation();render()});family.addEventListener(eventName,event=>{event.stopPropagation();render()})}
 query.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();event.stopPropagation()}});
 article.addEventListener('change',render);
 clear.onclick=()=>{query.value='';family.value='';render();query.focus()};render();
}
'''
